30	@Component(service = IstanzaDomandaBandoFinder.class)
31	public class IstanzaDomandaBandoFinderImpl extends IstanzaDomandaBandoFinderBaseImpl implements IstanzaDomandaBandoFinder{
32	
33	    @Override
34	    public List<IstanzaDomandaBando> findByDomandaBandoIdAndTipoForm(long domandaBandoId, String tipoForm, IstanzaDomandaBandoFilters filters, int start, int end) {
35	        DynamicQuery istanzaQuery = createFiltersQuery(domandaBandoId, Collections.singletonList(tipoForm), filters);
36	        istanzaQuery.addOrder(OrderFactoryUtil.asc("createDate"));
37	        return istanzaDomandaBandoPersistence.findWithDynamicQuery(istanzaQuery, start, end);
38	    }
39	
40	    @Override
41	    public long countByDomandaBandoIdAndTipoForm(long domandaBandoId, List<String> tipoForm, IstanzaDomandaBandoFilters filters) {
42	        DynamicQuery istanzaQuery = createFiltersQuery(domandaBandoId, tipoForm, filters);
43	        return istanzaDomandaBandoPersistence.countWithDynamicQuery(istanzaQuery);
44	    }
45	
46	    private DynamicQuery createFiltersQuery(long domandaBandoId, List<String> tipoFormList, IstanzaDomandaBandoFilters filters) {
47	        ClassLoader classLoader = getClass().getClassLoader();
48	
49	        DynamicQuery bandoIdQuery = DynamicQueryFactoryUtil.forClass(DomandaBando.class, classLoader);
50	        bandoIdQuery.add(RestrictionsFactoryUtil.eq("domandaBandoId", domandaBandoId));
51	        bandoIdQuery.setProjection(PropertyFactoryUtil.forName("bandoId"));
52	
53	        DynamicQuery formQuery = DynamicQueryFactoryUtil.forClass(BandoForm.class, classLoader);
54	        formQuery.add(RestrictionsFactoryUtil.in("tipoForm", tipoFormList));
55	        formQuery.add(PropertyFactoryUtil.forName("bandoId").in(bandoIdQuery));
56	        formQuery.setProjection(PropertyFactoryUtil.forName("formId"));
57	
58	        DynamicQuery istanzaQuery = DynamicQueryFactoryUtil.forClass(IstanzaDomandaBando.class, classLoader);
59	        istanzaQuery.add(RestrictionsFactoryUtil.eq("domandaBandoId", domandaBandoId));
60	        istanzaQuery.add(PropertyFactoryUtil.forName("formId").in(formQuery));
61	
62	        if (Validator.isNotNull(filters)) {
63	            if (Validator.isNotNull(filters.getStatoIn())) {
64	                istanzaQuery.add(RestrictionsFactoryUtil.in("stato", filters.getStatoIn()));
65	            }
66	
67	            if (Validator.isNotNull(filters.getStatoNotIn())) {
68	                istanzaQuery.add(RestrictionsFactoryUtil.not(RestrictionsFactoryUtil.in("stato", filters.getStatoNotIn())));
69	            }
70	
71	            if(filters.isEscludiIstanzeTerminiCompilazioneScaduti()){
72	                Date dataSistema = new Date();
73	
74	                Criterion scadute = RestrictionsFactoryUtil.and(
75	                        RestrictionsFactoryUtil.eq("stato", "NON_VALIDATA"),
76	                        RestrictionsFactoryUtil.and(
77	                                RestrictionsFactoryUtil.isNotNull("dataInizioInserimento"),
78	                                RestrictionsFactoryUtil.and(
79	                                        RestrictionsFactoryUtil.isNotNull("dataFineInserimento"),
80	                                        RestrictionsFactoryUtil.and(
81	                                                RestrictionsFactoryUtil.lt("dataInizioInserimento", dataSistema),
82	                                                RestrictionsFactoryUtil.lt("dataFineInserimento", dataSistema)
83	                                        )
84	                                )
85	                        )
86	                );
87	
88	                istanzaQuery.add(RestrictionsFactoryUtil.not(scadute));
89	            }
90	        }
91	
92	        return istanzaQuery;
93	    }
