95	    @Override
96	    public List<IstanzaDomandaBando> findByDomandaBandoIdAndListaFormId(long domandaBandoId, List<Long> listFormId) {
97	        ClassLoader classLoader = getClass().getClassLoader();
98	
99	        DynamicQuery dynamicQuery = DynamicQueryFactoryUtil.forClass(IstanzaDomandaBando.class, classLoader);
100	        dynamicQuery.add(RestrictionsFactoryUtil.eq("domandaBandoId", domandaBandoId));
101	        dynamicQuery.add(RestrictionsFactoryUtil.in("formId", listFormId));
102	
103	        return istanzaDomandaBandoPersistence.findWithDynamicQuery(dynamicQuery);
104	    }
