106	    @Override
107	    public List<IstanzaDomandaBando> findByDomandaBandoIdAndFormIdNotIn(long domandaBandoId, List<Long> listFormId) {
108	        ClassLoader classLoader = getClass().getClassLoader();
109	
110	        DynamicQuery dynamicQuery = DynamicQueryFactoryUtil.forClass(IstanzaDomandaBando.class, classLoader);
111	        dynamicQuery.add(RestrictionsFactoryUtil.eq("domandaBandoId", domandaBandoId));
112	        dynamicQuery.add(RestrictionsFactoryUtil.not(RestrictionsFactoryUtil.in("formId", listFormId)));
113	
114	        return istanzaDomandaBandoPersistence.findWithDynamicQuery(dynamicQuery);
115	    }
116	
117	    public long countByDomandaBandoIdAndListaFormId(long domandaBandoId, List<Long> listaFormId) {
118	        if (Validator.isNull(listaFormId)) return 0;
119	
120	        DynamicQuery dq = DynamicQueryFactoryUtil.forClass(IstanzaDomandaBando.class, getClass().getClassLoader())
121	                .add(RestrictionsFactoryUtil.eq("domandaBandoId", domandaBandoId))
122	                .add(RestrictionsFactoryUtil.in("formId", listaFormId))
123	                .setProjection(ProjectionFactoryUtil.rowCount());
124	
125	        return (Long) countWithDynamicQuery(dq);
126	    }
