130	    @Override
131	    public List<IstanzaDomandaBando> findByDomandaBandoIdAndTipoFormList(long domandaBandoId, List<String> tipoFormList, IstanzaDomandaBandoFilters filters, int start, int end) {
132	        DynamicQuery istanzaQuery = createFiltersQuery(domandaBandoId, tipoFormList, filters);
133	        istanzaQuery.addOrder(OrderFactoryUtil.asc("createDate"));
134	        return istanzaDomandaBandoPersistence.findWithDynamicQuery(istanzaQuery, start, end);
