137	    @Override
138	    public List<Long> findFormIdByBandoIdAndTipoForm(long bandoId, List<String> tipoForm, long domandaBandoId){
139	        DynamicQuery dynamicQuery = BandoFormLocalServiceUtil.dynamicQuery();
140	
141	        dynamicQuery.add(RestrictionsFactoryUtil.eq("bandoId", bandoId));
142	        dynamicQuery.add(RestrictionsFactoryUtil.in("tipoForm", tipoForm));
143	        dynamicQuery.setProjection(PropertyFactoryUtil.forName("formId"));
144	
145	        DynamicQuery istanzaDomandaBandoDynamicQuery = dynamicQuery();
146	        istanzaDomandaBandoDynamicQuery.add(RestrictionsFactoryUtil.eq("domandaBandoId", domandaBandoId));
147	        istanzaDomandaBandoDynamicQuery.add(PropertyFactoryUtil.forName("formId").in(dynamicQuery));
148	        istanzaDomandaBandoDynamicQuery.setProjection(PropertyFactoryUtil.forName("formId"));
149	
150	        return dynamicQuery(istanzaDomandaBandoDynamicQuery);
151	    }
