153	    @Override
154	    public List<IstanzaDomandaBando> findIstanzeDomandeBandoByDomandaBandoIdAndStato(long domandaBandoId, String stato) {
155	
156	        DynamicQuery domandaBandoIntegrazioneQuery = DomandaBandoIntegrazioneLocalServiceUtil.dynamicQuery();
157	        domandaBandoIntegrazioneQuery.add(RestrictionsFactoryUtil.isNotNull("dataProtocollo"));
158	        domandaBandoIntegrazioneQuery.add(RestrictionsFactoryUtil.isNotNull("numeroProtocollo"));
159	        domandaBandoIntegrazioneQuery.setProjection(PropertyFactoryUtil.forName("istanzaDomandaBandoId"));
160	
161	        DynamicQuery dynamicQuery = DynamicQueryFactoryUtil.forClass(IstanzaDomandaBando.class, getClass().getClassLoader());
162	        dynamicQuery.add(RestrictionsFactoryUtil.eq("domandaBandoId", domandaBandoId));
163	        dynamicQuery.add(RestrictionsFactoryUtil.eq("stato", stato));
164	        dynamicQuery.add(RestrictionsFactoryUtil.not(PropertyFactoryUtil.forName("istanzaDomandaBandoId").in(domandaBandoIntegrazioneQuery)));
165	
166	        return istanzaDomandaBandoPersistence.findWithDynamicQuery(dynamicQuery);
167	    }
