200	    public List<IstanzaDomandaBando> findByStatoOrFormIdList(String stato, List<Long> listFormId) {
201	
202	        DynamicQuery istanzaQuery = dynamicQuery();
203	        Junction orJunction = RestrictionsFactoryUtil.disjunction();
204	
205	        // Condizione 1: stato = valore passato in ingresso
206	        orJunction.add(RestrictionsFactoryUtil.eq("stato", stato));
207	
208	        // Condizione 2: istanza principale
209	        orJunction.add(PropertyFactoryUtil.forName("formId").in(listFormId));
210	        istanzaQuery.add(orJunction);
211	
212	        List<IstanzaDomandaBando> listaIstanze = istanzaDomandaBandoPersistence.findWithDynamicQuery(istanzaQuery);
213	
214	        return listaIstanze;
215	
216	    }
