218	    @Override
219	    public IstanzaDomandaBando findByDomandaBandoIdAndFormPrincipale(long domandaBandoId) {
220	        DynamicQuery formQuery = FormLocalServiceUtil.dynamicQuery();
221	        formQuery.add(RestrictionsFactoryUtil.eq("principale", true));
222	        formQuery.setProjection(PropertyFactoryUtil.forName("formId"));
223	        List<Long> formPrincipaliIds = FormLocalServiceUtil.dynamicQuery(formQuery);
224	
225	        if (formPrincipaliIds == null || formPrincipaliIds.isEmpty()) {
226	            return null;
227	        }
228	
229	        DynamicQuery istanzaQuery = DynamicQueryFactoryUtil.forClass(IstanzaDomandaBando.class, getClass().getClassLoader());
230	        istanzaQuery.add(RestrictionsFactoryUtil.eq("domandaBandoId", domandaBandoId));
231	        istanzaQuery.add(RestrictionsFactoryUtil.in("formId", formPrincipaliIds));
232	
233	        List<IstanzaDomandaBando> risultati = istanzaDomandaBandoPersistence.findWithDynamicQuery(istanzaQuery);
234	
235	        return risultati.isEmpty() ? null : risultati.get(risultati.size() - 1);
236	    }
