package it.servizidigitali.gestionebandi.service.persistence.impl;

import com.liferay.portal.kernel.dao.orm.Criterion;
import com.liferay.portal.kernel.dao.orm.DynamicQuery;
import com.liferay.portal.kernel.dao.orm.DynamicQueryFactoryUtil;
import com.liferay.portal.kernel.dao.orm.Junction;
import com.liferay.portal.kernel.dao.orm.OrderFactoryUtil;
import com.liferay.portal.kernel.dao.orm.ProjectionFactoryUtil;
import com.liferay.portal.kernel.dao.orm.PropertyFactoryUtil;
import com.liferay.portal.kernel.dao.orm.RestrictionsFactoryUtil;
import com.liferay.portal.kernel.util.PortalClassLoaderUtil;
import com.liferay.portal.kernel.util.Validator;
import it.servizidigitali.gestionebandi.model.BandoForm;
import it.servizidigitali.gestionebandi.model.DomandaBando;
import it.servizidigitali.gestionebandi.model.IstanzaDomandaBando;
import it.servizidigitali.gestionebandi.model.IstanzaDomandaBandoFilters;
import it.servizidigitali.gestionebandi.model.TermineBando;
import it.servizidigitali.gestionebandi.service.BandoFormLocalServiceUtil;
import it.servizidigitali.gestionebandi.service.DomandaBandoIntegrazioneLocalServiceUtil;
import it.servizidigitali.gestionebandi.service.persistence.IstanzaDomandaBandoFinder;
import it.servizidigitali.gestioneforms.service.FormLocalServiceUtil;
import org.osgi.service.component.annotations.Component;

import java.util.Collections;
import java.util.Date;
import java.util.List;

import static it.servizidigitali.gestionebandi.service.IstanzaDomandaBandoLocalServiceUtil.dynamicQuery;

@Component(service = IstanzaDomandaBandoFinder.class)
public class IstanzaDomandaBandoFinderImpl extends IstanzaDomandaBandoFinderBaseImpl implements IstanzaDomandaBandoFinder{

    @Override
    public List<IstanzaDomandaBando> findByDomandaBandoIdAndTipoForm(long domandaBandoId, String tipoForm, IstanzaDomandaBandoFilters filters, int start, int end) {
        DynamicQuery istanzaQuery = createFiltersQuery(domandaBandoId, Collections.singletonList(tipoForm), filters);
        istanzaQuery.addOrder(OrderFactoryUtil.asc("createDate"));
        return istanzaDomandaBandoPersistence.findWithDynamicQuery(istanzaQuery, start, end);
    }

    @Override
    public long countByDomandaBandoIdAndTipoForm(long domandaBandoId, List<String> tipoForm, IstanzaDomandaBandoFilters filters) {
        DynamicQuery istanzaQuery = createFiltersQuery(domandaBandoId, tipoForm, filters);
        return istanzaDomandaBandoPersistence.countWithDynamicQuery(istanzaQuery);
    }

    private DynamicQuery createFiltersQuery(long domandaBandoId, List<String> tipoFormList, IstanzaDomandaBandoFilters filters) {
        ClassLoader classLoader = getClass().getClassLoader();

        DynamicQuery bandoIdQuery = DynamicQueryFactoryUtil.forClass(DomandaBando.class, classLoader);
        bandoIdQuery.add(RestrictionsFactoryUtil.eq("domandaBandoId", domandaBandoId));
        bandoIdQuery.setProjection(PropertyFactoryUtil.forName("bandoId"));

        DynamicQuery formQuery = DynamicQueryFactoryUtil.forClass(BandoForm.class, classLoader);
        formQuery.add(RestrictionsFactoryUtil.in("tipoForm", tipoFormList));
        formQuery.add(PropertyFactoryUtil.forName("bandoId").in(bandoIdQuery));
        formQuery.setProjection(PropertyFactoryUtil.forName("formId"));

        DynamicQuery istanzaQuery = DynamicQueryFactoryUtil.forClass(IstanzaDomandaBando.class, classLoader);
        istanzaQuery.add(RestrictionsFactoryUtil.eq("domandaBandoId", domandaBandoId));
        istanzaQuery.add(PropertyFactoryUtil.forName("formId").in(formQuery));

        if (Validator.isNotNull(filters)) {
            if (Validator.isNotNull(filters.getStatoIn())) {
                istanzaQuery.add(RestrictionsFactoryUtil.in("stato", filters.getStatoIn()));
            }

            if (Validator.isNotNull(filters.getStatoNotIn())) {
                istanzaQuery.add(RestrictionsFactoryUtil.not(RestrictionsFactoryUtil.in("stato", filters.getStatoNotIn())));
            }

            if(filters.isEscludiIstanzeTerminiCompilazioneScaduti()){
                Date dataSistema = new Date();

                Criterion scadute = RestrictionsFactoryUtil.and(
                        RestrictionsFactoryUtil.eq("stato", "NON_VALIDATA"),
                        RestrictionsFactoryUtil.and(
                                RestrictionsFactoryUtil.isNotNull("dataInizioInserimento"),
                                RestrictionsFactoryUtil.and(
                                        RestrictionsFactoryUtil.isNotNull("dataFineInserimento"),
                                        RestrictionsFactoryUtil.and(
                                                RestrictionsFactoryUtil.lt("dataInizioInserimento", dataSistema),
                                                RestrictionsFactoryUtil.lt("dataFineInserimento", dataSistema)
                                        )
                                )
                        )
                );

                istanzaQuery.add(RestrictionsFactoryUtil.not(scadute));
            }
        }

        return istanzaQuery;
    }

    @Override
    public List<IstanzaDomandaBando> findByDomandaBandoIdAndListaFormId(long domandaBandoId, List<Long> listFormId) {
        ClassLoader classLoader = getClass().getClassLoader();

        DynamicQuery dynamicQuery = DynamicQueryFactoryUtil.forClass(IstanzaDomandaBando.class, classLoader);
        dynamicQuery.add(RestrictionsFactoryUtil.eq("domandaBandoId", domandaBandoId));
        dynamicQuery.add(RestrictionsFactoryUtil.in("formId", listFormId));

        return istanzaDomandaBandoPersistence.findWithDynamicQuery(dynamicQuery);
    }

    @Override
    public List<IstanzaDomandaBando> findByDomandaBandoIdAndFormIdNotIn(long domandaBandoId, List<Long> listFormId) {
        ClassLoader classLoader = getClass().getClassLoader();

        DynamicQuery dynamicQuery = DynamicQueryFactoryUtil.forClass(IstanzaDomandaBando.class, classLoader);
        dynamicQuery.add(RestrictionsFactoryUtil.eq("domandaBandoId", domandaBandoId));
        dynamicQuery.add(RestrictionsFactoryUtil.not(RestrictionsFactoryUtil.in("formId", listFormId)));

        return istanzaDomandaBandoPersistence.findWithDynamicQuery(dynamicQuery);
    }

    public long countByDomandaBandoIdAndListaFormId(long domandaBandoId, List<Long> listaFormId) {
        if (Validator.isNull(listaFormId)) return 0;

        DynamicQuery dq = DynamicQueryFactoryUtil.forClass(IstanzaDomandaBando.class, getClass().getClassLoader())
                .add(RestrictionsFactoryUtil.eq("domandaBandoId", domandaBandoId))
                .add(RestrictionsFactoryUtil.in("formId", listaFormId))
                .setProjection(ProjectionFactoryUtil.rowCount());

        return (Long) countWithDynamicQuery(dq);
    }



    @Override
    public List<IstanzaDomandaBando> findByDomandaBandoIdAndTipoFormList(long domandaBandoId, List<String> tipoFormList, IstanzaDomandaBandoFilters filters, int start, int end) {
        DynamicQuery istanzaQuery = createFiltersQuery(domandaBandoId, tipoFormList, filters);
        istanzaQuery.addOrder(OrderFactoryUtil.asc("createDate"));
        return istanzaDomandaBandoPersistence.findWithDynamicQuery(istanzaQuery, start, end);
    }

    @Override
    public List<Long> findFormIdByBandoIdAndTipoForm(long bandoId, List<String> tipoForm, long domandaBandoId){
        DynamicQuery dynamicQuery = BandoFormLocalServiceUtil.dynamicQuery();

        dynamicQuery.add(RestrictionsFactoryUtil.eq("bandoId", bandoId));
        dynamicQuery.add(RestrictionsFactoryUtil.in("tipoForm", tipoForm));
        dynamicQuery.setProjection(PropertyFactoryUtil.forName("formId"));

        DynamicQuery istanzaDomandaBandoDynamicQuery = dynamicQuery();
        istanzaDomandaBandoDynamicQuery.add(RestrictionsFactoryUtil.eq("domandaBandoId", domandaBandoId));
        istanzaDomandaBandoDynamicQuery.add(PropertyFactoryUtil.forName("formId").in(dynamicQuery));
        istanzaDomandaBandoDynamicQuery.setProjection(PropertyFactoryUtil.forName("formId"));

        return dynamicQuery(istanzaDomandaBandoDynamicQuery);
    }

    @Override
    public List<IstanzaDomandaBando> findIstanzeDomandeBandoByDomandaBandoIdAndStato(long domandaBandoId, String stato) {

        DynamicQuery domandaBandoIntegrazioneQuery = DomandaBandoIntegrazioneLocalServiceUtil.dynamicQuery();
        domandaBandoIntegrazioneQuery.add(RestrictionsFactoryUtil.isNotNull("dataProtocollo"));
        domandaBandoIntegrazioneQuery.add(RestrictionsFactoryUtil.isNotNull("numeroProtocollo"));
        domandaBandoIntegrazioneQuery.setProjection(PropertyFactoryUtil.forName("istanzaDomandaBandoId"));

        DynamicQuery dynamicQuery = DynamicQueryFactoryUtil.forClass(IstanzaDomandaBando.class, getClass().getClassLoader());
        dynamicQuery.add(RestrictionsFactoryUtil.eq("domandaBandoId", domandaBandoId));
        dynamicQuery.add(RestrictionsFactoryUtil.eq("stato", stato));
        dynamicQuery.add(RestrictionsFactoryUtil.not(PropertyFactoryUtil.forName("istanzaDomandaBandoId").in(domandaBandoIntegrazioneQuery)));

        return istanzaDomandaBandoPersistence.findWithDynamicQuery(dynamicQuery);
    }

    @Override
    public List<IstanzaDomandaBando> findByListaFormIdAndNotProtocollatoAndStato(List<Long> listFormId, String stato) {
        ClassLoader classLoader = getClass().getClassLoader();
        DynamicQuery domandaBandoIntegrazioneQuery = DomandaBandoIntegrazioneLocalServiceUtil.dynamicQuery();
        domandaBandoIntegrazioneQuery.add(RestrictionsFactoryUtil.isNotNull("dataProtocollo"));
        domandaBandoIntegrazioneQuery.add(RestrictionsFactoryUtil.isNotNull("numeroProtocollo"));
        domandaBandoIntegrazioneQuery.setProjection(PropertyFactoryUtil.forName("istanzaDomandaBandoId"));

        DynamicQuery dynamicQuery = DynamicQueryFactoryUtil.forClass(IstanzaDomandaBando.class, classLoader);
        dynamicQuery.add(RestrictionsFactoryUtil.in("formId", listFormId));
        dynamicQuery.add(RestrictionsFactoryUtil.eq("stato", stato));
        dynamicQuery.add(RestrictionsFactoryUtil.not(PropertyFactoryUtil.forName("istanzaDomandaBandoId").in(domandaBandoIntegrazioneQuery)));

        return istanzaDomandaBandoPersistence.findWithDynamicQuery(dynamicQuery);
    }

    @Override
    public long findCountRichiesteIntegrazioni(Long domandaBandoId, List<Long> listFormId) {
        DynamicQuery dynamicQuery = dynamicQuery();
        dynamicQuery.add(RestrictionsFactoryUtil.eq("domandaBandoId", domandaBandoId));
        dynamicQuery.add(RestrictionsFactoryUtil.in("formId", listFormId));
        return istanzaDomandaBandoPersistence.countWithDynamicQuery(dynamicQuery);
    }

    @Override
    public List<IstanzaDomandaBando> findByDomandaBandoIdAndTipoForms(long domandaBandoId, List<String> tipoForms, IstanzaDomandaBandoFilters filters, int start, int end) {
        DynamicQuery istanzaQuery = createFiltersQuery(domandaBandoId, tipoForms, filters);
        istanzaQuery.addOrder(OrderFactoryUtil.asc("createDate"));
        return istanzaDomandaBandoPersistence.findWithDynamicQuery(istanzaQuery, start, end);
    }

    public List<IstanzaDomandaBando> findByStatoOrFormIdList(String stato, List<Long> listFormId) {

        DynamicQuery istanzaQuery = dynamicQuery();
        Junction orJunction = RestrictionsFactoryUtil.disjunction();

        // Condizione 1: stato = valore passato in ingresso
        orJunction.add(RestrictionsFactoryUtil.eq("stato", stato));

        // Condizione 2: istanza principale
        orJunction.add(PropertyFactoryUtil.forName("formId").in(listFormId));
        istanzaQuery.add(orJunction);

        List<IstanzaDomandaBando> listaIstanze = istanzaDomandaBandoPersistence.findWithDynamicQuery(istanzaQuery);

        return listaIstanze;

    }

    @Override
    public IstanzaDomandaBando findByDomandaBandoIdAndFormPrincipale(long domandaBandoId) {
        DynamicQuery formQuery = FormLocalServiceUtil.dynamicQuery();
        formQuery.add(RestrictionsFactoryUtil.eq("principale", true));
        formQuery.setProjection(PropertyFactoryUtil.forName("formId"));
        List<Long> formPrincipaliIds = FormLocalServiceUtil.dynamicQuery(formQuery);

        if (formPrincipaliIds == null || formPrincipaliIds.isEmpty()) {
            return null;
        }

        DynamicQuery istanzaQuery = DynamicQueryFactoryUtil.forClass(IstanzaDomandaBando.class, getClass().getClassLoader());
        istanzaQuery.add(RestrictionsFactoryUtil.eq("domandaBandoId", domandaBandoId));
        istanzaQuery.add(RestrictionsFactoryUtil.in("formId", formPrincipaliIds));

        List<IstanzaDomandaBando> risultati = istanzaDomandaBandoPersistence.findWithDynamicQuery(istanzaQuery);

        return risultati.isEmpty() ? null : risultati.get(risultati.size() - 1);
    }

    @Override
    public IstanzaDomandaBando findUltimaIstanzaDomandaBandoByDomandaBandoIdAndTipoFormAndFormIdAndStatoNotIn(long domandaBandoId, String tipoForm, long formId, List<String> statiNotIn) {

        ClassLoader classLoader = getClass().getClassLoader();

        DynamicQuery bandoIdQuery = DynamicQueryFactoryUtil.forClass(DomandaBando.class, classLoader);
        bandoIdQuery.add(RestrictionsFactoryUtil.eq("domandaBandoId", domandaBandoId));
        bandoIdQuery.setProjection(PropertyFactoryUtil.forName("bandoId"));

        DynamicQuery formQuery = DynamicQueryFactoryUtil.forClass(BandoForm.class, classLoader);
        formQuery.add(RestrictionsFactoryUtil.eq("tipoForm", tipoForm));
        formQuery.add(PropertyFactoryUtil.forName("bandoId").in(bandoIdQuery));
        formQuery.setProjection(PropertyFactoryUtil.forName("formId"));

        DynamicQuery istanzaQuery = DynamicQueryFactoryUtil.forClass(IstanzaDomandaBando.class, classLoader);

        istanzaQuery.add(RestrictionsFactoryUtil.eq("domandaBandoId", domandaBandoId));
        istanzaQuery.add(PropertyFactoryUtil.forName("formId").in(formQuery));

        istanzaQuery.add(RestrictionsFactoryUtil.eq("formId", formId));

        istanzaQuery.add(RestrictionsFactoryUtil.isNotNull("createDate"));

        if (Validator.isNotNull(statiNotIn)) {
            istanzaQuery.add(
                    RestrictionsFactoryUtil.not(
                            RestrictionsFactoryUtil.in("stato", statiNotIn)
                    )
            );
        }

        istanzaQuery.addOrder(OrderFactoryUtil.desc("createDate"));

        List<IstanzaDomandaBando> risultati =
                istanzaDomandaBandoPersistence.findWithDynamicQuery(istanzaQuery, 0, 1);

        return risultati.isEmpty() ? null : risultati.get(0);
    }

    @Override
    public long countIstanzeDomandaBandoExcludingStatesAndForms(long domandaBandoId, List<String> statiNotIn, List<Long> formIdNotIn) {
        ClassLoader classLoader = getClass().getClassLoader();

        DynamicQuery dq = DynamicQueryFactoryUtil.forClass(IstanzaDomandaBando.class, classLoader);

        dq.add(RestrictionsFactoryUtil.eq("domandaBandoId", domandaBandoId));

        if (Validator.isNotNull(statiNotIn) && !statiNotIn.isEmpty()) {
            dq.add(RestrictionsFactoryUtil.not(RestrictionsFactoryUtil.in("stato", statiNotIn)));
        }

        if (Validator.isNotNull(formIdNotIn) && !formIdNotIn.isEmpty()) {
            dq.add(RestrictionsFactoryUtil.not(RestrictionsFactoryUtil.in("formId", formIdNotIn)));
        }

        dq.setProjection(ProjectionFactoryUtil.rowCount());

        return istanzaDomandaBandoPersistence.countWithDynamicQuery(dq);
    }

    @Override
    public List<IstanzaDomandaBando> findIstanzeDaNotificareScadenza(Date referenceDate, String codiceNotificaScadenza) {

        ClassLoader classLoader = getClass().getClassLoader();

        DynamicQuery bandiAbilitati = DynamicQueryFactoryUtil.forClass(TermineBando.class, classLoader);
        bandiAbilitati.add(PropertyFactoryUtil.forName("codice").eq(codiceNotificaScadenza));
        bandiAbilitati.setProjection(ProjectionFactoryUtil.property("bandoId"));

        DynamicQuery domandeSuBandiAbilitati = DynamicQueryFactoryUtil.forClass(DomandaBando.class, classLoader);
        domandeSuBandiAbilitati.add(PropertyFactoryUtil.forName("bandoId").in(bandiAbilitati));
        domandeSuBandiAbilitati.setProjection(ProjectionFactoryUtil.property("domandaBandoId"));

        DynamicQuery query = dynamicQuery();
        query.add(PropertyFactoryUtil.forName("notificaInviata").eq(false));
        query.add(PropertyFactoryUtil.forName("dataInvio").isNull());
        query.add(PropertyFactoryUtil.forName("dataFineInserimento").isNotNull());
        query.add(PropertyFactoryUtil.forName("dataFineInserimento").ge(referenceDate));
        query.add(PropertyFactoryUtil.forName("domandaBandoId").in(domandeSuBandiAbilitati));

        return dynamicQuery(query);

    }
}

