/**
 * Risolve la vecchia utenza interna di un operatore migrato a SPID a partire dal custom field
 * (Expando) {@code old_screen_name} valorizzato sull'utente.
 *
 * <p>
 * Per gli utenti non migrati (Expando vuoto) entrambi i metodi restituiscono {@code null}: la
 * logica chiamante deve in quel caso lavorare con la sola identità corrente, senza regressioni.
 * </p>
 */
public interface OldUserResolver {

	/**
	 * @param userId id dell'utente SPID corrente
	 * @return il vecchio screenName interno (es. "mario.rossi"), oppure {@code null} se l'Expando è vuoto
	 */
	String getOldScreenName(long userId);

	/**
	 * @param userId id dell'utente SPID corrente
	 * @return il vecchio userId numerico interno, oppure {@code null} se l'Expando è vuoto o
	 *         la vecchia utenza non è più presente
	 */
	Long getOldUserId(long userId);

	/**
	 * Variante che parte dallo screenName corrente anziché dallo userId: risolve l'utente per
	 * screenName nella company indicata e ne restituisce il vecchio screenName interno.
	 *
	 * @param companyId id della company
	 * @param screenName screenName corrente (per i cittadini/SPID coincide con il codice fiscale)
	 * @return il vecchio screenName interno (es. "mario.rossi"), oppure {@code null} se non risolvibile
	 */
	String getOldScreenNameByScreenName(long companyId, String screenName);

}

